  </main>

  <script>
    const state = {
      deleted: false,
      statusMessage: ""
    };

    function PreviewArtwork() {
      return `
        <svg viewBox="0 0 800 600" role="img" aria-labelledby="preview-art-title preview-art-desc" xmlns="http://www.w3.org/2000/svg">
          <title id="preview-art-title">Night landscape image preview</title>
