              <stop offset="100%" stop-color="#08111e" />
            </linearGradient>
            <linearGradient id="glow" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="#a78bfa" />
              <stop offset="100%" stop-color="#8db2ff" />
            </linearGradient>
          </defs>
          <rect width="800" height="600" fill="url(#sky)" />
          <circle cx="620" cy="120" r="54" fill="#f1f5ff" opacity="0.92" />
          <circle cx="620" cy="120" r="88" fill="#c6d7ff" opacity="0.08" />
          <g fill="#d4ddff">
            <circle cx="130" cy="110" r="2" />
            <circle cx="210" cy="80" r="1.8" />
            <circle cx="300" cy="122" r="2" />
            <circle cx="352" cy="76" r="1.6" />
            <circle cx="512" cy="64" r="2" />
            <circle cx="688" cy="58" r="1.7" />
          </g>
          <path d="M0 310L100 260L170 290L278 180L380 288L490 140L620 320L800 220V600H0Z" fill="#141f31" />
          <path d="M0 360L112 298L220 358L330 238L450 372L590 214L720 350L800 318V600H0Z" fill="#24324f" />
          <path d="M0 390H800V600H0Z" fill="url(#water)" />
          <path d="M415 280C468 310 543 332 629 336C563 358 472 360 404 352Z" fill="url(#glow)" opacity="0.22" />
          <path d="M0 448C102 430 198 428 288 446C382 464 506 468 610 446C688 430 748 428 800 434V600H0Z" fill="#0f1726" opacity="0.75" />
        </svg>
      `;
    }

    function Hero() {
      return `
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Image library</p>
          <h1 id="page-title">Preview your selected image before you remove it.</h1>
          <p class="hero-copy">
            Review the artwork, check its details, and use the delete action below the preview if you want to remove it from your library.
          </p>
        </section>
      `;
    }

    function PreviewCard() {
      return `
        <article id="image-preview" class="panel preview-card" aria-labelledby="preview-heading">
          <h2 id="preview-heading" class="sr-only">Image preview</h2>
          <div class="preview-media">
            ${PreviewArtwork()}
          </div>
          <div class="card-footer">
            <div class="image-meta">
              <strong>Midnight Lake</strong><br>
              4032 × 3024 px · Added to your nature collection
            </div>
            <div class="actions">
              <button type="button" class="trigger">Delete image</button>
            </div>
          </div>
        </article>
      `;
    }

    function DetailsPanel() {
      return `
        <aside id="image-details" class="panel details-panel" aria-labelledby="details-heading">
          <h2 id="details-heading">Image details</h2>
          <dl class="detail-list">
            <div>
              <dt>Album</dt>
              <dd>Nightscapes</dd>
            </div>
            <div>
              <dt>Captured</dt>
              <dd>October 18, 2025</dd>
            </div>
            <div>
              <dt>License</dt>
              <dd>Private library asset</dd>
            </div>
            <div>
              <dt>Status</dt>
              <dd>Available for sync</dd>
            </div>
          </dl>
        </aside>
      `;
    }

    function EmptyState() {
      return `
        <section class="panel empty-state" aria-labelledby="delete-result-heading">
          <h2 id="delete-result-heading" tabindex="-1" data-delete-result>Image deleted</h2>
          <p>The image has been removed from your library. You can continue browsing your collection from here.</p>
          <a class="button-link" href="#page-title">Return to preview header</a>
        </section>
      `;
    }

    function ConfirmDeleteDialog() {
      return `
        <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
          <div class="dialog-body">
            <h2 id="delete-dialog-title" class="dialog-title">Delete this image from your library?</h2>
            <p id="delete-dialog-description" class="dialog-copy">
              This will permanently remove <strong>Midnight Lake</strong> from your saved collection. This action cannot be undone.
            </p>
            <div class="dialog-actions">
              <button type="button" id="cancel-delete">Cancel</button>
              <button type="button" id="confirm-delete" class="danger">Delete image</button>
            </div>
          </div>
        </dialog>
      `;
    }

    function App() {
      return `
        ${Hero()}
        <div class="content-grid">
          ${state.deleted ? EmptyState() : PreviewCard()}
          ${DetailsPanel()}
        </div>
        ${state.deleted ? "" : ConfirmDeleteDialog()}
      `;
    }

    function attachHandlers() {
      const trigger = document.querySelector(".trigger");
      const dialog = document.getElementById("delete-dialog");
      const cancelButton = document.getElementById("cancel-delete");
      const confirmButton = document.getElementById("confirm-delete");

      if (!trigger || !dialog || !cancelButton || !confirmButton) {
        return;
      }

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        dialog.close("delete");
        state.deleted = true;
        state.statusMessage = "Image deleted from your library.";
        render("[data-delete-result]");
      });
    }

    function render(focusSelector) {
      document.getElementById("root").innerHTML = App();
      document.getElementById("status-message").textContent = state.statusMessage;
      attachHandlers();

      if (focusSelector) {
        const focusTarget = document.querySelector(focusSelector);
        if (focusTarget) {
          focusTarget.focus();
        }
      }
    }

    render();
  </script>
</body>
</html>
