     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       color: var(--color-text);
       background:
         radial-gradient(circle at top left, #1d2740 0, transparent 34%),
         radial-gradient(circle at top right, #26153f 0, transparent 28%),
