       background: rgba(7, 10, 18, 0.72);
       backdrop-filter: blur(18px);
     }

     .brand {
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     .top-nav {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
