     .top-nav a {
       padding: 0.5rem 0.8rem;
       border-radius: 999px;
       color: var(--color-muted-text);
       text-decoration: none;
     }

     .top-nav a[aria-current="page"] {
       background: rgba(141, 178, 255, 0.16);
       color: var(--color-text);
     }

     .page-shell {
       width: min(1100px, calc(100% - 2rem));
       margin: 0 auto;
       padding: clamp(1.5rem, 4vw, 3rem) 0 4rem;
     }

     .hero {
       margin-bottom: 1.75rem;
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       color: var(--color-accent);
       font-size: 0.85rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1,
     h2,
     h3,
     p {
       margin-top: 0;
     }

     h1 {
       margin-bottom: 0.9rem;
       font-size: clamp(2rem, 5vw, 3.6rem);
       line-height: 1.05;
     }

     .hero-copy {
       max-width: 58ch;
       color: var(--color-muted-text);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     .content-grid {
       display: grid;
       grid-template-columns: minmax(0, 1.6fr) minmax(280px, 0.9fr);
       gap: 1.5rem;
       align-items: start;
     }

     .panel {
       border: 1px solid rgba(255, 255, 255, 0.08);
       border-radius: var(--radius-xl);
       background: linear-gradient(180deg, rgba(26, 34, 51, 0.94), rgba(16, 22, 35, 0.97));
       box-shadow: var(--shadow-md);
     }

     .preview-card {
       padding: clamp(1rem, 2vw, 1.4rem);
     }

     .preview-media {
       overflow: hidden;
       border: 1px solid rgba(255, 255, 255, 0.08);
       border-radius: calc(var(--radius-xl) - 8px);
       background: #060913;
       aspect-ratio: 4 / 3;
       box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.03);
     }

     .preview-media svg {
       display: block;
       width: 100%;
       height: 100%;
     }

     .card-footer {
       display: flex;
       justify-content: space-between;
       align-items: center;
       gap: 1rem;
       margin-top: 1rem;
       flex-wrap: wrap;
     }

     .image-meta {
       color: var(--color-muted-text);
       line-height: 1.6;
     }

     .actions {
       display: flex;
       gap: 0.75rem;
       flex-wrap: wrap;
     }

     button,
     .button-link {
       border: 1px solid var(--color-border);
       border-radius: 999px;
       background: var(--color-surface);
       color: var(--color-text);
       cursor: pointer;
       padding: 0.85rem 1.15rem;
       transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
     }

     button:hover,
     .button-link:hover {
       transform: translateY(-1px);
       border-color: #51648d;
     }

     .trigger {
       border-color: #874255;
       background: linear-gradient(180deg, #4c2030, #391722);
       color: #ffe6eb;
     }

     .trigger:hover,
     .danger:hover {
       border-color: #ca6278;
       background: linear-gradient(180deg, #5c2437, #461b2a);
     }

     .button-link {
       display: inline-flex;
       align-items: center;
       justify-content: center;
       text-decoration: none;
     }

     .details-panel,
     .empty-state {
       padding: 1.4rem;
     }

     .detail-list {
       display: grid;
       gap: 1rem;
       margin: 0;
     }

     .detail-list div {
       padding-bottom: 1rem;
       border-bottom: 1px solid rgba(255, 255, 255, 0.08);
     }

     .detail-list div:last-child {
       padding-bottom: 0;
       border-bottom: 0;
     }

     dt {
       margin-bottom: 0.35rem;
       color: var(--color-muted-text);
       font-size: 0.88rem;
     }

     dd {
       margin: 0;
