  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 } });
  const url = 'file://' + path.join(process.cwd(), 'index.html');
  const results = [];

  async function audit(name, prepare) {
    await page.goto(url, { waitUntil: 'load' });
    if (prepare) await prepare();
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const run = await page.evaluate(async () => await window.axe.run(document, { resultTypes: ['violations'] }));
    results.push({
      label: name,
      violations: run.violations.map(v => ({
        id: v.id,
        impact: v.impact,
        tags: v.tags,
        targets: v.nodes.map(n => n.target)
      }))
    });
  }

  await audit('default');
  await audit('dialog-open', async () => {
    await page.click('.trigger');
    await page.waitForSelector('dialog[open]');
  });
  await audit('deleted-state', async () => {
    await page.click('.trigger');
    await page.click('#confirm-delete');
    await page.waitForSelector('[data-delete-result]');
  });

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
  const wcag = results.flatMap(r => r.violations.filter(v => !v.tags.includes('best-practice')));
  process.exit(wcag.length ? 1 : 0);
})();
