     function EmptyState() {
       return `
         <section class="panel empty-state" aria-labelledby="delete-result-heading">
           <h2 id="delete-result-heading" tabindex="-1" data-delete-result>Image deleted</h2>
           <p>The image has been removed from your library. You can continue browsing your collection from here.</p>
